import json,re
from pathlib import Path
root=Path(__file__).resolve().parents[3]
scratch=Path(__file__).resolve().parent
clean=root/'build/t26-package/s10-delivery/clean-source'
tree=clean/'build/.ninja'
package=root/'build/t26-package/s10-delivery/candidate'
dev=json.loads((root/'docs/etc/evidence/t26-s10-controls-development.json').read_text(encoding='utf-8'))
s9=json.loads((root/'docs/etc/evidence/t26-s9-delivery.json').read_text(encoding='utf-8'))
products={'run16s.exe','demo.exe','ntw16s32.dll','ntw16s64.dll','ntw2ks32.dll','ntw2ks64.dll','ntwshk32.dll','ntwshk64.dll'}
candidates=[('S9',c) for c in s9['post_publication']['cases']]
for run in dev['runs']:
 result=run.get('result')
 if isinstance(result,list):candidates.extend((run['name'],c) for c in result if isinstance(c,dict) and (c.get('command') or c.get('args')))
 models=run.get('models')
 if isinstance(models,dict):candidates.extend((run['name'],c) for c in models.get('cases',[]))

def convert(s,arch):
 if not isinstance(s,str):return str(s)
 norm=s.replace('\\','/')
 if norm.rsplit('/',1)[-1].lower() in products:return str(package/norm.rsplit('/',1)[-1])
 if norm.endswith('/tools/run_test.py'):return str(clean/'tools/run_test.py')
 m=re.search(r'/(x86|x64)/(.+)$',norm)
 if m:return str(tree/m[1]/m[2])
 if norm.endswith('/x86') and '/build/' in norm:return str(tree/'x86')
 if norm.endswith('/x64') and '/build/' in norm:return str(tree/'x64')
 if '/build/' in norm:
  if arch in ['x86','x64'] and norm.lower().endswith(('.exe','.dll')):
   return str(tree/arch/norm.rsplit('/',1)[-1])
  raise ValueError('unmapped scratch '+s)
 return s

rows={};errors=[]
for source,c in candidates:
 args=c.get('args',c.get('command'))
 if not isinstance(args,list):continue
 arch=c.get('arch',c.get('architecture'))
 if arch not in ['x86','x64']:
  match=re.search(r'[/\\](x86|x64)[/\\]',' '.join(args));arch=match[1] if match else None
 try: command=[convert(a,arch) for a in args]
 except ValueError as e:errors.append({'source':source,'error':str(e)});continue
 output=c.get('output','')+c.get('stdout','')+c.get('stderr','')
 markers=c.get('markers') or ([c['marker']] if c.get('marker') else [])
 if not markers:
  m=re.search(r'(?m)^([A-Z0-9_ ]*(?:_OK| PASS|_PASS))\b',output)
  if m:markers=[m[1]]
 row={'source':source,'name':c.get('name','native'),'arch':arch,'command':command,'markers':markers,'timeout':min(int(c.get('timeout',90)),120),'known_failure':bool(c.get('known_failure')),'cwd':convert(c['cwd'],arch) if c.get('cwd') else None}
 # Addresses are resolved against the new snapshot in the runner.
 if any(Path(a).name=='core-vcl-mdi-ref.exe' for a in command):command[-1]='@ATTACHMENT_RVA@'
 key=command[command.index('--')+1:] if any('run_test.py' in a for a in command) and '--' in command else command
 rows[tuple(key)]=row
plan={'scope':'Same snapshot actual published package, current-desktop owned native fixtures only; no computer-use/private desktops. Prior tested command recipes deduplicated; no physical input claim.','cases':list(rows.values()),'mapping_errors':errors}
(scratch/'plan.json').write_bytes((json.dumps(plan,ensure_ascii=False,indent=2)+'\n').encode('utf-8'))
print('PLAN cases',len(rows),'mapping_errors',len(errors),'no_marker',sum(not c['markers'] for c in rows.values()))
for e in errors:print(e)

