   rows[k]={'source':'S10-public-contract','name':t['name'],'arch':arch,'command':command,'markers':[],'timeout':90,'known_failure':False,'cwd':str(tree/arch)}
 symbols={}
 for arch in ['x86','x64']:
  dll=package/('ntw16s32.dll' if arch=='x86' else 'ntw16s64.dll');data=dll.read_bytes();pe=struct.unpack_from('<I',data,0x3c)[0];opt=pe+24
  base=struct.unpack_from('<I' if arch=='x86' else '<Q',data,opt+(28 if arch=='x86' else 24))[0]
  r=subprocess.run([cache(arch,'CMAKE_NM'),'-n',str(dll)],capture_output=True,text=True,timeout=30);assert r.returncode==0
  name='_attachment_proc@24' if arch=='x86' else 'attachment_proc';m=re.search(r'^([0-9a-fA-F]+)\s+[tT]\s+'+re.escape(name)+r'$',r.stdout,re.M);assert m
  offset=int(m[1],16)-base;assert 0<offset<struct.unpack_from('<I',data,opt+56)[0];symbols[arch]={'symbol':name,'rva':format(offset,'x'),'sha256':digest(dll)}
 for c in rows.values():
  c['command']=[symbols[c['arch']]['rva'] if a=='@ATTACHMENT_RVA@' else a for a in c['command']]
  for a in c['command']:
   if re.match(r'^[A-Za-z]:[/\\]',a):assert Path(a).exists(),(c['name'],a)
  assert all('ntvdm64' not in a.lower() and 'softpc' not in a.lower() for a in c['command'])
