 print('READY',len(rows),'cases',flush=True)
else:
 plan=read(scratch/'ready-plan.json');pub=read(root/'build/t26-package/s10-publish/result.json');assert pub['status']=='passed'
 for name,h in plan['sha256'].items():
  for dest in [package,root/'assets',Path('O:/winnt')]:assert digest(dest/name)==h,(dest,name)
 result={'scope':plan['scope'],'sha256':plan['sha256'],'symbols':plan['symbols'],'planned':len(plan['cases']),'cases':[],'status':'running'}
 begin=0
 if '--resume' in sys.argv:
  previous=read(scratch/'first-attempt.json');assert previous['cases'][-1].get('timeout_reached');result['cases']=previous['cases'][:-1];begin=len(result['cases']);result['continuation']='Historical bool timeout=False was parsed as0; fixed scratch driver only; original attempt retained, no live owned child after native CIM.'
